/* ===== shared helpers for role views ===== */
const PST=s=>chip({paid:T('مدفوعة','Paid'),due:T('مستحقة','Due'),overdue:T('متأخرة','Overdue'),upcoming:T('قادمة','Upcoming')}[s],{paid:'ok',due:'info',overdue:'bad',upcoming:''}[s]);
const MST=s=>chip({new:T('جديد','New'),assigned:T('تم التعيين','Assigned'),in_progress:T('قيد التنفيذ','In progress'),done:T('مكتمل','Done')}[s],{new:'brand',assigned:'info',in_progress:'warn',done:'ok'}[s]);
const PRI=p=>chip({high:T('عاجلة','Urgent'),normal:T('عادية','Normal'),low:T('منخفضة','Low')}[p],{high:'bad',normal:'',low:''}[p]);
const dayLbl=n=>n<0?T(`متأخر ${-n} يوماً`,`${-n}d overdue`):n===0?T('اليوم','Today'):T(`بعد ${n} يوم`,`in ${n}d`);
function incomeSeries(n){
  const out=[];const ids=myContracts().map(c=>c.id);
  for(let i=n-1;i>=0;i--){const d=addM(new Date(TODAY.getFullYear(),TODAY.getMonth(),1),-i);const k=monthKey(d);
    const ps=DB.payments.filter(p=>p.kind==='rent'&&ids.includes(p.c)&&monthKey(p.due)===k&&p.status!=='upcoming');
    out.push({l:mon(d.getMonth()),paid:ps.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0),exp:ps.reduce((a,p)=>a+p.amount,0)});}
  return out;
}
const curMonthPays=()=>myPays().filter(p=>p.kind==='rent'&&monthKey(p.due)===monthKey(TODAY));
const kpi=(l,v,d,i)=>{const tone={alert:'b',clock:'w',refresh:'w',building:'s',file:'s',users:'s',star:'w',tag:'s'}[i]||'';return `<div class="kpi">${i?`<span class="kic ${tone}">${ic(i,18)}</span>`:''}<div class="l">${l}</div><div class="v">${v}</div>${d?`<div class="d">${d}</div>`:''}</div>`};
const assistBox=chips=>`<form data-form="ask" class="assist">${ic('sparkle',20)}<input id="askIn" placeholder="${T('اكتب طلبك، مثال: أريد تجديد عقد شقة في المحرق','Type a request, e.g. renew an apartment lease in Muharraq')}" aria-label="${T('المساعد الذكي','Smart assistant')}" autocomplete="off"><button class="btn pri">${T('ابدأ','Go')}</button></form><div class="chips" style="margin-top:10px">${chips.map(c=>`<button type="button" data-a="chip" data-t="${esc(c)}">${c}</button>`).join('')}</div>`;

V.overview=()=>S.role==='landlord'?ovLandlord():S.role==='tenant'?ovTenant():ovAdmin();

function ovLandlord(){
  const units=myUnits();const occ=units.filter(u=>unitStatus(u)==='occupied').length;
  const cm=curMonthPays();const exp=cm.reduce((a,p)=>a+p.amount,0),col=cm.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0);
  const over=myPays().filter(p=>p.status==='overdue'&&p.kind==='rent');const ren=renewalList();
  const att=[];
  over.forEach(p=>{const c=ctOf(p.c);att.push({ic:'card',k:'bad',t:T(`إيجار متأخر: ${uname(c.tenant)}`,`Overdue rent: ${uname(c.tenant)}`),s:`${money(p.amount)} · ${dayLbl(days(p.due,TODAY))}`,btn:btn(T('تذكير','Remind'),'remind',{id:p.id},'sm','send')})});
  ren.forEach(c=>att.push({ic:'refresh',k:'info',t:T(`ينتهي عقد ${uname(c.tenant)}`,`${uname(c.tenant)}'s lease is ending`),s:T(`خلال ${days(end(c),TODAY)} يوماً`,`in ${days(end(c),TODAY)} days`)+(c.renewal&&c.renewal.state==='requested'?' · '+T('طلب تجديد','renewal requested'):''),btn:btn(T('تجديد','Renew'),'nav',{v:'renewals'},'sm')}));
  myMaint().filter(m=>m.st==='new').forEach(m=>att.push({ic:'wrench',k:'warn',t:L(m.title),s:`${unitLabel(unitOf(m.unit))} · ${rel(m.created)}`,btn:btn(T('عرض','Open'),'modal',{t:'maint',id:m.id},'sm')}));
  myContracts().filter(c=>c.status==='pending_sign').forEach(c=>att.push({ic:'pen',k:'teal',t:T(`بانتظار توقيع ${uname(c.tenant)}`,`Waiting for ${uname(c.tenant)} to sign`),s:c.no,btn:btn(T('فتح العقد','Open'),'modal',{t:'contract',id:c.id},'sm')}));
  const inc=incomeSeries(6);
  return pageHead(T(`مرحباً، ${dispName().split(' ')[0]}`,`Welcome back, ${dispName().split(' ')[0]}`),T('ملخص عقاراتك اليوم، '+fd(TODAY),'Your portfolio today, '+fd(TODAY)),btn(T('عقد جديد','New contract'),'modal',{t:'wizard'},'brand','plus')+btn(T('إضافة عقار','Add property'),'modal',{t:'propadd'},'','building'))+
  `<div style="margin-bottom:20px">${assistBox([T('إنشاء عقد جديد','Create a new contract'),T('تجديد عقد في المحرق','Renew a lease in Muharraq'),T('متابعة الإيجارات المتأخرة','Follow up overdue rent'),T('طلبات الصيانة','Maintenance requests')])}</div>
  <div class="kpis">${kpi(T('المحصّل هذا الشهر','Collected this month'),`${fmt(col)}<small>/ ${fmt(exp)} ${cur()}</small>`,`<div class="pg" style="margin-top:6px"><i style="width:${pct(col,exp)}%"></i></div>`,'coins')}${kpi(T('نسبة الإشغال','Occupancy'),`${pct(occ,units.length)}%`,T(`${occ} من ${units.length} وحدة مؤجرة`,`${occ} of ${units.length} units let`),'building')}${kpi(T('متأخرات','Overdue'),`${fmt(over.reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,T(`${over.length} دفعات متأخرة`,`${over.length} late payments`),'alert')}${kpi(T('عقود تنتهي خلال 90 يوماً','Leases ending in 90 days'),ren.length,T('ابدأ التجديد مبكراً','Start renewing early'),'refresh')}</div>
  <div class="g2"><div class="card"><div class="ch"><h3>${T('الإيرادات — آخر 6 أشهر','Income — last 6 months')}</h3><div class="legend"><span><i style="background:var(--teal)"></i>${T('المحصّل','Collected')}</span><span><i style="background:var(--line)"></i>${T('المتوقع','Expected')}</span></div></div><div class="cb">${barChart(inc.map(i=>i.l),[inc.map(i=>i.exp),inc.map(i=>i.paid)],['var(--line)','var(--teal)'],{label:T('الإيرادات','Income')})}</div></div>
  <div class="card"><div class="ch"><h3>${T('يحتاج انتباهك','Needs your attention')}</h3>${chip(att.length,att.length?'brand nd':'nd')}</div>${att.slice(0,6).map(a=>`<div class="li"><span class="ii ${a.k}">${ic(a.ic,17)}</span><div class="tx"><div class="sm b">${esc(a.t)}</div><div class="xs mut3">${esc(a.s)}</div></div>${a.btn}</div>`).join('')||empty(T('كل شيء على ما يرام','All clear'),T('لا توجد إجراءات معلّقة.','No pending actions.'),'check')}</div></div>
  <div class="g2e"><div class="card"><div class="ch"><h3>${T('الإشغال حسب العقار','Occupancy by property')}</h3>${btn(T('العقارات','Properties'),'nav',{v:'properties'},'sm ghost')}</div><div class="cb">${myProps().map(p=>{const us=DB.units.filter(u=>u.prop===p.id);const o=us.filter(u=>unitStatus(u)==='occupied').length;return `<div style="margin-bottom:14px"><div class="row"><b class="sm" style="flex:1">${L(p.name)}</b><span class="xs mut3 num">${o}/${us.length}</span></div><div class="pg" style="margin-top:6px"><i style="width:${pct(o,us.length)}%"></i></div></div>`}).join('')}</div></div>
  <div class="card"><div class="ch"><h3>${T('آخر النشاطات','Recent activity')}</h3></div>${myNotifs().slice(0,4).map(n=>`<div class="li"><span class="ii ${NTY[n.ty][1]}">${ic(NTY[n.ty][0],17)}</span><div class="tx"><div class="sm b">${esc(T(n.ar,n.en))}</div><div class="xs mut3">${rel(n.t)}</div></div></div>`).join('')}</div></div>`;
}

function ovTenant(){
  const cs=myContracts().filter(c=>['active','pending_sign','pending_pay'].includes(c.status));const c=cs.find(x=>x.status==='active')||cs[0];
  if(!c)return pageHead(T('مرحباً','Welcome'),'')+`<div class="card">${empty(T('لا توجد عقود','No contracts'),'','file')}</div>`;
  const u=unitOf(c.unit),p=propOf(u.prop);const tot=days(end(c),c.start)+1,el=Math.max(0,Math.min(tot,days(TODAY,c.start)+1));const left=days(end(c),TODAY);
  const next=myPays().filter(x=>x.status!=='paid'&&(x.kind==='fee'||x.c===c.id)).sort((a,b)=>a.due-b.due)[0];
  const hist=myPays().filter(x=>x.status==='paid').sort((a,b)=>b.due-a.due).slice(0,4);const auto=!!DB.autopay;
  const pend=myContracts().filter(x=>['pending_sign','pending_pay'].includes(x.status));
  return pageHead(T(`مرحباً، ${dispName().split(' ')[0]}`,`Welcome, ${dispName().split(' ')[0]}`),T('كل ما يخص إيجارك في مكان واحد','Everything about your tenancy in one place'),btn(T('طلب صيانة','Maintenance request'),'modal',{t:'maintnew'},'brand','wrench'))+
  (pend.length?`<div class="card" style="margin-bottom:20px;border-color:var(--info)"><div class="li"><span class="ii info">${ic('pen',18)}</span><div class="tx"><div class="b">${T('لديك عقد بانتظار إجراء منك','You have a contract waiting for action')}</div><div class="sm mut">${pend[0].no} · ${pend[0].status==='pending_sign'?T('وقّع العقد إلكترونياً','Sign the contract electronically'):T('ادفع رسوم التسجيل لتفعيل العقد','Pay the registration fee to activate it')}</div></div>${btn(T('فتح','Open'),'modal',{t:'contract',id:pend[0].id},'pri sm')}</div></div>`:'')+
  `<div style="margin-bottom:20px">${assistBox([T('دفع الإيجار','Pay my rent'),T('طلب تجديد العقد','Request lease renewal'),T('التبليغ عن عطل','Report a problem'),T('التحقق من عقد','Verify a contract')])}</div>
  <div class="g2" style="margin-top:0"><div class="card"><div class="cb"><div class="row wrapf"><div style="flex:1;min-width:200px"><div class="xs mut3">${esc(c.no)}</div><h3 style="font-size:20px;margin:2px 0">${unitLabel(u)}</h3><div class="sm mut">${ic('pin',14)} ${L(AREAS[p.area])} · ${L(UT[u.type])} · ${u.beds?u.beds+' '+T('غرف','bd')+' · ':''}${u.size} m²</div></div>${CSTATUS(cst(c))}</div>
   <div style="margin:22px 0 8px" class="row"><span class="xs mut3">${fd(c.start)}</span><div class="pg" style="flex:1"><i style="width:${pct(el,tot)}%"></i></div><span class="xs mut3">${fd(end(c))}</span></div>
   <div class="sm ${left<=60?'':'mut'}" style="${left<=60?'color:var(--warn)':''}">${left>=0?T(`متبقٍ ${left} يوماً على انتهاء العقد`,`${left} days left on your lease`):''}</div>
   <hr class="hr"><div class="fg" style="grid-template-columns:repeat(3,minmax(0,1fr))"><div><div class="xs mut3">${T('الإيجار الشهري','Monthly rent')}</div><div class="b" style="font-size:18px">${money(c.rent)}</div></div><div><div class="xs mut3">${T('مبلغ التأمين','Deposit')}</div><div class="b" style="font-size:18px">${money(c.deposit)}</div></div><div><div class="xs mut3">${T('المؤجر','Landlord')}</div><div class="b">${uname(c.landlord)}</div></div></div>
   <div class="row wrapf" style="margin-top:18px">${btn(T('تفاصيل العقد','Contract details'),'modal',{t:'contract',id:c.id},'','file')}${left<=90&&left>=0?btn(T('طلب تجديد','Request renewal'),'nav',{v:'renewals'},'pri','refresh'):''}</div></div></div>
  <div class="col"><div class="card" style="border-color:${next&&next.status==='overdue'?'var(--bad)':'var(--line)'}"><div class="cb"><div class="xs mut3">${T('الدفعة القادمة','Next payment')}</div>${next?`<div style="font-size:34px;font-weight:600;line-height:1.2;margin:4px 0" class="num">${money(next.amount)}</div><div class="sm ${next.status==='overdue'?'dn':'mut'}">${next.kind==='fee'?T('رسوم تسجيل العقد','Contract registration fee')+' · ':''}${fd(next.due)} · ${dayLbl(days(next.due,TODAY))}</div><div style="margin-top:14px">${btn(T('ادفع الآن','Pay now'),'modal',{t:'pay',id:next.id},'brand lg','card')}</div>`:`<div style="font-size:20px;font-weight:600;margin:6px 0">${T('لا مبالغ مستحقة','Nothing due')}</div><div class="sm mut">${T('أنت على اطلاع كامل بمدفوعاتك.','You are all paid up.')}</div>`}</div></div>
   <div class="card"><div class="cb row"><div style="flex:1"><div class="b">${T('السداد التلقائي','Auto-pay')}</div><div class="xs mut3">${T('يُخصم الإيجار في تاريخ الاستحقاق','Rent is charged on the due date')}</div></div>${sw(auto,'autopay')}</div></div></div></div>
  <div class="g2e"><div class="card"><div class="ch"><h3>${T('آخر المدفوعات','Recent payments')}</h3>${btn(T('الكل','All'),'nav',{v:'payments'},'sm ghost')}</div>${hist.map(h=>`<div class="li"><span class="ii ok">${ic('receipt',17)}</span><div class="tx"><div class="sm b">${mon(h.due.getMonth(),1)} ${h.due.getFullYear()}</div><div class="xs mut3"><bdi dir="ltr">${h.receipt}</bdi> · ${fd(h.paidOn)}</div></div><b class="num">${money(h.amount)}</b></div>`).join('')||empty(T('لا مدفوعات بعد','No payments yet'),'','card')}</div>
  <div class="card"><div class="ch"><h3>${T('طلبات الصيانة','Maintenance requests')}</h3>${btn(T('الكل','All'),'nav',{v:'maintenance'},'sm ghost')}</div>${myMaint().slice(0,3).map(m=>`<div class="li click" data-a="modal" data-t="maint" data-id="${m.id}"><span class="ii warn">${ic('wrench',17)}</span><div class="tx"><div class="sm b">${L(m.title)}</div><div class="xs mut3">${rel(m.created)}</div></div>${MST(m.st)}</div>`).join('')||empty(T('لا توجد طلبات','No requests'),'','wrench')}</div></div>`;
}
CH.autopay=async el=>{const on=el.checked;try{await API.post('/api/payments/autopay',{enabled:on});DB.autopay=on;toast(on?T('تم تفعيل السداد التلقائي','Auto-pay enabled'):T('تم إيقاف السداد التلقائي','Auto-pay turned off'))}catch(e){el.checked=!on;apiError(e,'تعذّر حفظ الإعداد','Could not save the setting')}};

/* ===== properties ===== */
V.properties=()=>S.role==='admin'?propsAdmin():propsLandlord();
function propsLandlord(){
  const q=S.f.props.q.toLowerCase();const ps=myProps().filter(p=>!q||(p.name.ar+p.name.en+L(AREAS[p.area])).toLowerCase().includes(q));
  return pageHead(T('العقارات','Properties'),T('أضف عقاراتك وأدر وحداتها وحالة الإشغال','Add your properties and manage units and occupancy'),btn(T('إضافة عقار','Add property'),'modal',{t:'propadd'},'pri','plus'))+
  `<div class="tb">${searchBox('propQ',S.f.props.q,T('ابحث باسم العقار أو المنطقة…','Search by property or area…'),'props')}</div>
  <div class="g4">${ps.map(p=>{const us=DB.units.filter(u=>u.prop===p.id);const o=us.filter(u=>unitStatus(u)==='occupied').length;const inc=us.filter(u=>unitStatus(u)==='occupied').reduce((a,u)=>a+u.rent,0);
   return `<div class="card" style="display:flex;flex-direction:column"><div class="cb col" style="flex:1"><div class="row"><div style="flex:1"><b>${L(p.name)}</b><div class="sm mut">${ic('pin',13)} ${L(AREAS[p.area])} · ${L(PT[p.type])}</div></div>${p.verified?chip(T('موثّق','Verified'),'ok'):chip(T('قيد التوثيق','Pending'),'warn')}</div>
   <div><div class="row sm"><span class="mut">${T('الإشغال','Occupancy')}</span><span class="sp"></span><b class="num">${o}/${us.length}</b></div><div class="pg" style="margin-top:6px"><i style="width:${pct(o,us.length)}%"></i></div></div>
   <div class="row sm"><span class="mut">${T('الدخل الشهري','Monthly income')}</span><span class="sp"></span><b class="num">${money(inc)}</b></div></div>
   <div class="row" style="padding:0 20px 18px">${btn(T('إدارة الوحدات','Manage units'),'modal',{t:'prop',id:p.id},'sm')}</div></div>`}).join('')||`<div class="card" style="grid-column:1/-1">${empty(T('لا توجد عقارات','No properties'),T('أضف عقارك الأول لتبدأ.','Add your first property to get started.'),'building')}</div>`}</div>`;
}
IN.props=v=>{S.f.props.q=v;renderView()};
MOD.propadd=()=>({title:T('إضافة عقار','Add a property'),body:`<div class="fg">${field(T('اسم العقار','Property name'),inp('pName','','text','data-focus placeholder="'+T('مثال: برج الأمل','e.g. Al-Amal Tower')+'"'),'full')}${field(T('المنطقة','Area'),sel('pArea',Object.keys(AREAS).map(k=>[k,L(AREAS[k])]),'muh'))}${field(T('النوع','Type'),sel('pType',Object.keys(PT).map(k=>[k,L(PT[k])]),'building'))}${field(T('رقم سند الملكية','Title deed no.'),inp('pDeed','','text','dir="ltr" style="text-align:start" placeholder="MH-00000"'))}${field(T('عدد الوحدات','Number of units'),inp('pUnits','4','number','min="1" max="40"'))}<div class="full fld"><label class="lb">${T('سند الملكية','Title deed file')}</label><input type="file" class="in" id="pFile"><div class="hint">${T('يُراجع السند من الإدارة قبل التوثيق.','The deed is reviewed by administrators before verification.')}</div></div></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="propsave">${T('إضافة العقار','Add property')}</button>`});
A.propsave=async()=>{const n=val('pName').trim(),dd=val('pDeed').trim();if(!n||!dd){toast(T('أدخل الاسم ورقم السند','Enter the name and deed number'),true);return}
  try{await afterMutation(API.post('/api/properties',{name:n,area:val('pArea'),type:val('pType'),deed:dd,units:+val('pUnits')||1}));closeModal();toast(T('تمت إضافة العقار وأُرسل للتوثيق','Property added and sent for verification'))}
  catch(e){apiError(e,'تعذّر إضافة العقار','Could not add the property')}};
MOD.prop=d=>{const p=propOf(d.id),us=DB.units.filter(u=>u.prop===p.id);
  return {sheet:1,title:L(p.name),body:`<div class="row wrapf" style="margin-bottom:16px">${p.verified?chip(T('موثّق','Verified'),'ok'):chip(T('قيد التوثيق','Pending'),'warn')}${chip(rawL(AREAS[p.area]),'nd')}${chip(rawL(PT[p.type]),'nd')}<span class="xs mut3 num">${T('سند','Deed')}: ${esc(p.deed)}</span></div>
  ${table([{h:T('الوحدة','Unit'),f:u=>`<b>${L(UT[u.type])} ${esc(u.no)}</b><div class="xs mut3">${u.beds?u.beds+' '+T('غرف','bd')+' · ':''}${u.size} m²</div>`},{h:T('الإيجار','Rent'),f:u=>`<span class="num">${money(u.rent)}</span>`},{h:T('الحالة','Status'),f:u=>{const s=unitStatus(u);return chip({occupied:T('مؤجرة','Let'),vacant:T('شاغرة','Vacant'),reserved:T('محجوزة','Reserved'),maint:T('صيانة','Maintenance')}[s],{occupied:'ok',vacant:'warn',reserved:'info',maint:'bad'}[s])+(u.listed?' '+chip(T('معروضة','Listed'),'teal'):'')}},{h:'',c:'ac',f:u=>unitStatus(u)==='vacant'&&S.role==='landlord'?btn(u.listed?T('إيقاف العرض','Unlist'):T('اعرض للإيجار','List for rent'),'listunit',{id:u.id},'sm'):(unitStatus(u)==='vacant'&&S.role==='landlord'?'':'')}],us)}`,foot:S.role==='landlord'?`<button class="btn" data-a="modal" data-t="unitadd" data-id="${p.id}">${ic('plus',16)}${T('إضافة وحدة','Add unit')}</button><button class="btn pri" data-a="close">${T('إغلاق','Close')}</button>`:`<button class="btn pri" data-a="close">${T('إغلاق','Close')}</button>`};};
A.listunit=async d=>{const u=unitOf(d.id);const next=!u.listed;try{await API.post('/api/units/'+d.id+'/list',{listed:next});u.listed=next;rerenderModal();toast(next?T('تم عرض الوحدة للإيجار','Unit listed for rent'):T('تم إيقاف العرض','Listing removed'))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};
MOD.unitadd=d=>({title:T('إضافة وحدة','Add a unit'),cls:'narrow',body:`<div class="fg">${field(T('رقم الوحدة','Unit no.'),inp('uNo','','text','data-focus'))}${field(T('النوع','Type'),sel('uType',Object.keys(UT).map(k=>[k,L(UT[k])]),'apt'))}${field(T('غرف النوم','Bedrooms'),inp('uBeds','2','number','min="0"'))}${field(T('المساحة (م²)','Size (m²)'),inp('uSize','90','number','min="10"'))}${field(T('الإيجار الشهري','Monthly rent'),inp('uRent','300','number','min="1"'),'full')}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="unitsave" data-id="${d.id}">${T('إضافة','Add')}</button>`});
A.unitsave=async d=>{const no=val('uNo').trim();if(!no){toast(T('أدخل رقم الوحدة','Enter the unit number'),true);return}
  try{await API.post('/api/properties/'+d.id+'/units',{no,type:val('uType'),beds:+val('uBeds')||0,size:+val('uSize')||0,rent:+val('uRent')||0});await refresh();openModal('prop',{id:d.id});toast(T('تمت إضافة الوحدة','Unit added'))}catch(e){apiError(e,'تعذّر إضافة الوحدة','Could not add the unit')}};

/* ===== contracts ===== */
const CGROUPS=[['all',['ALL'],'الكل','All'],['active',['active','expiring'],'سارية','In force'],['expiring',['expiring'],'تنتهي قريباً','Expiring'],['pending',['pending_sign','pending_pay'],'بانتظار إجراء','Pending'],['review',['under_review','disputed'],'مراجعة ونزاعات','Review & disputes'],['ended',['expired','terminated'],'منتهية','Ended']];
V.contracts=()=>{
  const F=S.f.contracts;const q=F.q.toLowerCase();const all=myContracts();
  const match=c=>{const g=CGROUPS.find(x=>x[0]===F.st);const s=cst(c);return g[1][0]==='ALL'||g[1].includes(s)};
  const txt=c=>{const u=unitOf(c.unit),p=propOf(u.prop);return (c.no+userOf(c.tenant).name.ar+userOf(c.tenant).name.en+userOf(c.landlord).name.ar+userOf(c.landlord).name.en+p.name.ar+p.name.en+AREAS[p.area].ar+AREAS[p.area].en).toLowerCase()};
  const l=all.filter(c=>match(c)&&(!q||txt(c).includes(q)));
  const cols=[{h:T('رقم العقد','Contract'),f:c=>`<b class="num" dir="ltr">${esc(c.no)}</b>`},
   {h:S.role==='tenant'?T('المؤجر','Landlord'):T('المستأجر','Tenant'),f:c=>{const n=uname(S.role==='tenant'?c.landlord:c.tenant);return `<div class="ent">${ava(n)}<b>${esc(n)}</b></div>`}},
   ...(S.role==='admin'?[{h:T('المؤجر','Landlord'),f:c=>uname(c.landlord)}]:[]),
   {h:T('الوحدة','Unit'),f:c=>{const u=unitOf(c.unit);return `<b>${L(UT[u.type])} ${esc(u.no)}</b><small style="display:block" class="xs mut3">${L(propOf(u.prop).name)}</small>`}},
   {h:T('المدة','Term'),f:c=>`<span class="sm">${fd(c.start)}</span><small class="xs mut3" style="display:block">→ ${fd(end(c))}</small>`},
   {h:T('الإيجار','Rent'),f:c=>`<b class="num">${money(c.rent)}</b>`},{h:T('الحالة','Status'),f:c=>CSTATUS(cst(c))},
   {h:'',c:'ac',f:c=>ibtn(S.lang==='ar'?'left':'right','modal',{t:'contract',id:c.id},T('فتح','Open'))}];
  return pageHead(S.role==='tenant'?T('عقدي','My contract'):T('العقود','Contracts'),S.role==='admin'?T('مراجعة كل العقود المسجّلة في المنصة','Review all contracts registered on the platform'):T('كل عقود الإيجار وحالتها وتواريخها','All lease contracts, statuses and dates'),(S.role==='landlord'?btn(T('عقد جديد','New contract'),'modal',{t:'wizard'},'brand','plus'):'')+btn(T('تصدير','Export'),'modal',{t:'export',kind:'contracts'},'','download'))+
  `<div class="tb">${searchBox('ctQ',F.q,T('ابحث برقم العقد أو الاسم أو العقار أو المنطقة…','Search by number, name, property or area…'),'ct')}${seg(CGROUPS.map(g=>[g[0],T(g[2],g[3]),all.filter(c=>g[1][0]==='ALL'||g[1].includes(cst(c))).length]),F.st,'seg','data-k="contracts.st"')}</div>${table(cols,l.map(c=>Object.assign({},c,{_a:'openct'})),empty(T('لا توجد عقود مطابقة','No matching contracts'),T('غيّر الفلتر أو ابدأ عقداً جديداً.','Change the filter or start a new contract.'),'file'))}`;
};
IN.ct=v=>{S.f.contracts.q=v;renderView()};

A.openct=d=>openModal('contract',{id:d.id});
/* contract sheet */
MOD.contract=d=>{
  const c=ctOf(d.id);if(!c)return {title:'',body:''};const u=unitOf(c.unit),p=propOf(u.prop),s=cst(c);const L_=userOf(c.landlord),Tn=userOf(c.tenant);
  const fee=DB.payments.find(x=>x.c===c.id&&x.kind==='fee');const feePaid=!fee||fee.status==='paid';
  const steps=[[T('إنشاء العقد','Contract created'),true,fd(c.created)],[T('توقيع المؤجر','Landlord signed'),c.signedL,''],[T('توقيع المستأجر','Tenant signed'),c.signedT,''],[T('دفع رسوم التسجيل','Registration fee paid'),feePaid&&c.signedT,''],[T('العقد فعّال','Contract in force'),['active','expired','disputed'].includes(c.status)&&days(TODAY,c.start)>=0,fd(c.start)],[T('انتهاء العقد','Contract ends'),false,fd(end(c))]];
  const firstNot=steps.findIndex(x=>!x[1]);
  const pays=DB.payments.filter(x=>x.c===c.id&&x.kind==='rent').sort((a,b)=>b.due-a.due).slice(0,5);
  let act='';const role=S.role;
  if(role==='landlord'&&c.landlord===S.uid){
    if(c.status==='pending_sign'&&!c.signedL)act+=btn(T('وقّع العقد','Sign contract'),'csign',{id:c.id,who:'landlord'},'brand','pen');
    if(['active'].includes(c.status))act+=btn(T('عرض تجديد','Renewal offer'),'modal',{t:'renewoffer',id:c.id},'pri','refresh')+btn(T('إنهاء العقد','Terminate'),'modal',{t:'terminate',id:c.id},'danger');
  }
  if(role==='tenant'&&c.tenant===S.uid){
    if(c.status==='pending_sign'&&c.signedL&&!c.signedT)act+=btn(T('وقّع العقد','Sign contract'),'csign',{id:c.id,who:'tenant'},'brand','pen');
    if(c.status==='pending_pay'&&fee)act+=btn(T('ادفع الرسوم','Pay fee')+' · '+money(fee.amount),'modal',{t:'pay',id:fee.id},'brand','card');
    if(c.status==='active')act+=btn(T('طلب صيانة','Maintenance'),'modal',{t:'maintnew'},'','wrench')+(days(end(c),TODAY)<=90?btn(T('طلب تجديد','Request renewal'),'crenew',{id:c.id},'pri','refresh'):'');
  }
  if(role==='admin'){
    if(c.status==='under_review')act+=btn(T('اعتماد العقد','Approve'),'capprove',{id:c.id},'pri','check')+btn(T('رفض','Reject'),'modal',{t:'reject',k:'contract',id:c.id},'danger');
    if(['active','disputed'].includes(c.status))act+=btn(T('تعليق العقد','Suspend'),'modal',{t:'terminate',id:c.id},'danger');
    if(c.status==='disputed')act+=btn(T('إغلاق النزاع','Resolve dispute'),'cresolve',{id:c.id},'pri','check');
  }
  const chkItems=[['keys',T('تسليم المفاتيح','Keys handed over')],['meters',T('تسجيل قراءات العدادات','Meter readings recorded')],['photos',T('توثيق حالة الوحدة بالصور','Unit condition photographed')],['inv',T('جرد المحتويات','Inventory checked')]];
  return {sheet:1,title:`<span class="num" dir="ltr">${c.no}</span>`,aria:c.no,body:`
   <div class="row wrapf" style="margin-bottom:16px">${CSTATUS(s)}${c.utilities?chip(T('شامل الخدمات','Utilities included'),'teal'):''}${c.renewal?chip({requested:T('طلب تجديد','Renewal requested'),offered:T('عرض تجديد مُرسل','Renewal offered'),accepted:T('تم التجديد','Renewed'),declined:T('رُفض التجديد','Renewal declined')}[c.renewal.state],'info'):''}</div>
   ${c.flag?`<div class="verres bad" style="margin-bottom:16px">${ic('alert',22)}<div><b>${T('ملاحظة المراجعة','Review note')}</b><div class="sm">${L(c.flag)}</div></div></div>`:''}
   <div class="row wrapf" style="align-items:flex-start;gap:20px"><dl class="kv" style="flex:1;min-width:260px"><dt>${T('المؤجر','Landlord')}</dt><dd>${L(L_.name)}</dd><dt>${T('المستأجر','Tenant')}</dt><dd>${L(Tn.name)}</dd><dt>${T('العقار','Property')}</dt><dd>${L(p.name)}</dd><dt>${T('الوحدة','Unit')}</dt><dd>${L(UT[u.type])} ${esc(u.no)} · ${u.size} m²</dd><dt>${T('المدة','Term')}</dt><dd>${c.months} ${T('شهراً','months')}</dd><dt>${T('من – إلى','From – to')}</dt><dd>${fd(c.start)} – ${fd(end(c))}</dd><dt>${T('الإيجار','Rent')}</dt><dd class="num">${money(c.rent)} / ${c.freq==='monthly'?T('شهر','month'):T('ربع سنة','quarter')}</dd><dt>${T('مبلغ التأمين','Deposit')}</dt><dd class="num">${money(c.deposit)}</dd><dt>${T('يوم الاستحقاق','Due day')}</dt><dd>${c.dueDay}</dd></dl>${qrSvg(c.no)}</div>
   ${c.notes?`<div class="sm mut" style="margin-top:12px">${esc(c.notes)}</div>`:''}
   <hr class="hr"><h4 style="margin-bottom:12px">${T('مسار العقد','Contract timeline')}</h4><ul class="tl">${steps.map((x,i)=>`<li class="${x[1]?'done':i===firstNot?'now':''}"><i></i><div class="sm ${x[1]?'b':'mut'}">${x[0]}</div>${x[2]?`<div class="xs mut3">${x[2]}</div>`:''}</li>`).join('')}</ul>
   ${pays.length?`<hr class="hr"><h4 style="margin-bottom:8px">${T('الدفعات','Payments')}</h4>${pays.map(x=>`<div class="row sm" style="padding:6px 0"><span class="sp">${fd(x.due)}</span><b class="num">${money(x.amount)}</b>${PST(x.status)}</div>`).join('')}`:''}
   ${c.status==='active'&&role!=='admin'?`<hr class="hr"><h4 style="margin-bottom:8px">${T('قائمة الاستلام','Move-in checklist')}</h4>${chkItems.map(k=>`<label class="opt" style="margin-bottom:8px"><input type="checkbox" data-ch="chk" data-cid="${c.id}" data-k="${k[0]}" ${c.check[k[0]]?'checked':''}><span class="sm">${k[1]}</span></label>`).join('')}`:''}`,
   foot:`${act}<button class="btn" data-a="ctdoc" data-id="${c.id}">${ic('download',16)}${T('تنزيل العقد PDF','Download contract PDF')}</button><button class="btn ${act?'':'pri'}" data-a="close">${T('إغلاق','Close')}</button>`};
};
CH.chk=async el=>{const c=ctOf(el.dataset.cid);const k=el.dataset.k;const v=el.checked;c.check[k]=v;try{await API.post('/api/contracts/'+c.id+'/checklist',{key:k,value:v})}catch(e){el.checked=!v;apiError(e,'تعذّر الحفظ','Could not save')}};
A.crenew=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/renew-request'));closeModal();toast(T('تم إرسال طلب التجديد للمؤجر','Renewal request sent to the landlord'))}catch(e){apiError(e,'تعذّر إرسال الطلب','Could not send the request')}};
A.csign=d=>openModal('sign',{cid:d.id,who:d.who});
A.capprove=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/approve'));closeModal();toast(T('تم اعتماد العقد','Contract approved'))}catch(e){apiError(e,'تعذّر الاعتماد','Could not approve')}};
A.cresolve=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/resolve'));closeModal();toast(T('تم إغلاق النزاع','Dispute resolved'))}catch(e){apiError(e,'تعذّر الإغلاق','Could not resolve')}};
MOD.terminate=d=>{const c=ctOf(d.id);return {title:S.role==='admin'?T('تعليق العقد','Suspend contract'):T('إنهاء العقد','Terminate contract'),cls:'narrow',body:`<p class="mut sm" style="margin-bottom:14px">${esc(c.no)}</p><div class="col">${field(T('السبب','Reason'),sel('trWhy',[['agree',T('اتفاق الطرفين','Mutual agreement')],['breach',T('إخلال بالشروط','Breach of terms')],['nonpay',T('عدم سداد الإيجار','Non-payment')],['other',T('سبب آخر','Other')]],'agree'))}${field(T('ملاحظات','Notes'),'<textarea class="ta" id="trNote" style="min-height:70px"></textarea>')}</div>`,foot:`<button class="btn" data-a="close">${T('تراجع','Back')}</button><button class="btn danger" data-a="doterminate" data-id="${c.id}">${T('تأكيد','Confirm')}</button>`}};
A.doterminate=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/terminate'));closeModal();toast(T('تم تحديث حالة العقد','Contract status updated'))}catch(e){apiError(e,'تعذّر التنفيذ','Could not update the contract')}};

/* signature pad + sign modal */
const PAD={ink:false};
function initPad(){const c=$('#pad');if(!c)return;PAD.ink=false;c.width=Math.max(200,c.clientWidth||400);c.height=150;let ctx=null;try{ctx=c.getContext('2d')}catch(_){}if(!ctx)return;
  ctx.lineWidth=2.4;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=getComputedStyle(c).color;let dr=false;
  const pos=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};
  c.onpointerdown=e=>{dr=true;try{c.setPointerCapture(e.pointerId)}catch(_){}const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();PAD.ink=true;const h=$('#padHint');if(h)h.style.display='none'};
  c.onpointermove=e=>{if(!dr)return;const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()};c.onpointerup=c.onpointercancel=()=>{dr=false};}
A.padclear=()=>{const c=$('#pad');if(!c)return;const ctx=c.getContext&&c.getContext('2d');if(ctx)ctx.clearRect(0,0,c.width,c.height);PAD.ink=false;const h=$('#padHint');if(h)h.style.display=''};
const padHtml=()=>`<div style="position:relative"><canvas class="pad" id="pad" style="color:var(--ink)" aria-label="${T('منطقة التوقيع','Signature area')}"></canvas><span id="padHint" class="mut3 sm" style="position:absolute;inset:0;display:grid;place-items:center;pointer-events:none">${T('وقّع هنا بإصبعك أو الماوس','Sign here with your finger or mouse')}</span></div><div class="row" style="margin-top:8px"><span class="xs mut3">${T('توقيعك ملزم قانونياً وفق شروط المنصة','Your signature is binding under the platform terms')}</span><span class="sp"></span><button class="btn sm ghost" data-a="padclear">${T('مسح','Clear')}</button></div>`;
POST.sign=initPad;POST.wizard=d=>{if(S.modal.w&&S.modal.w.step===3)initPad()};
MOD.sign=d=>{const c=ctOf(d.cid);return {title:T('توقيع العقد','Sign contract'),cls:'narrow',body:`<p class="mut sm" style="margin-bottom:12px">${esc(c.no)} · ${L(propOf(unitOf(c.unit).prop).name)} · ${money(c.rent)}</p>${padHtml()}<label class="opt" style="margin-top:14px"><input type="checkbox" id="agree"><span class="sm">${T('أقرّ بأنني قرأت شروط العقد وأوافق عليها','I confirm that I have read and agree to the contract terms')}</span></label>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn brand" data-a="dosign" data-cid="${c.id}" data-who="${d.who}">${ic('pen',16)}${T('توقيع وإرسال','Sign & submit')}</button>`}};
A.dosign=async d=>{if(!PAD.ink){toast(T('ارسم توقيعك أولاً','Draw your signature first'),true);return}if(!chk('agree')){toast(T('يجب الموافقة على الشروط','You must accept the terms'),true);return}
  try{await afterMutation(API.post('/api/contracts/'+d.cid+'/sign',{as:d.who}));toast(T('تم التوقيع بنجاح','Signed successfully'));setTimeout(()=>openModal('contract',{id:d.cid}),50)}catch(e){apiError(e,'تعذّر التوقيع','Could not sign')}};

/* new contract wizard */
MOD.wizard=d=>{
  if(!S.modal.w){const vac=myUnits().filter(u=>unitStatus(u)==='vacant');const ft=DB.users.find(u=>u.role==='tenant'&&u.verified&&u.status==='active');const d0=addD(TODAY,7);S.modal.w={step:0,unit:vac[0]?vac[0].id:'',tenant:ft?ft.id:'',start:d0.toISOString().slice(0,10),months:12,rent:vac[0]?vac[0].rent:300,deposit:vac[0]?vac[0].rent:300,freq:'monthly',dueDay:1,utilities:false,notes:''};}
  const w=S.modal.w;const vac=myUnits().filter(u=>unitStatus(u)==='vacant');const dots=`<div class="steps-w">${[0,1,2,3].map(i=>`<i class="${i<=w.step?'on':''}"></i>`).join('')}</div>`;
  const names=[T('الوحدة','Unit'),T('المستأجر','Tenant'),T('الشروط','Terms'),T('المراجعة والتوقيع','Review & sign')];let body='';
  if(w.step===0)body=vac.length?`<div class="col">${vac.map(u=>`<label class="opt"><input type="radio" name="wzU" value="${u.id}" ${w.unit===u.id?'checked':''}><div style="flex:1"><b>${L(UT[u.type])} ${esc(u.no)} · ${L(propOf(u.prop).name)}</b><div class="xs mut3">${u.beds?u.beds+' '+T('غرف','bd')+' · ':''}${u.size} m²</div></div><b class="num">${money(u.rent)}</b></label>`).join('')}</div>`:empty(T('لا توجد وحدات شاغرة','No vacant units'),T('أضف وحدة أو أنهِ عقداً قائماً أولاً.','Add a unit or end an existing lease first.'),'building');
  if(w.step===1){const ts=DB.users.filter(u=>u.role==='tenant'&&u.verified&&u.status==='active');body=ts.length?`<div class="col">${field(T('اختر مستأجراً موثّقاً','Choose a verified tenant'),sel('wzT',ts.map(u=>[u.id,rawL(u.name)]),w.tenant),'',T('لتجربة التوقيع كمستأجر لاحقاً، سجّل خروجك وادخل بحساب المستأجر الذي اخترته.','To try signing as the tenant afterwards, sign out and sign back in as the tenant you picked.'))}</div>`:empty(T('لا يوجد مستأجرون موثّقون بعد','No verified tenants yet'),'','users');}
  if(w.step===2)body=`<div class="fg">${field(T('تاريخ البداية','Start date'),inp('wzStart',w.start,'date'))}${field(T('المدة','Term'),sel('wzMonths',[[6,'6 '+T('أشهر','months')],[12,'12 '+T('شهراً','months')],[24,'24 '+T('شهراً','months')],[36,'36 '+T('شهراً','months')]],w.months))}${field(T('الإيجار الشهري (د.ب)','Monthly rent (BD)'),inp('wzRent',w.rent,'number','min="1"'))}${field(T('مبلغ التأمين (د.ب)','Deposit (BD)'),inp('wzDep',w.deposit,'number','min="0"'))}${field(T('دورة السداد','Payment cycle'),sel('wzFreq',[['monthly',T('شهرياً','Monthly')],['quarterly',T('ربع سنوي','Quarterly')]],w.freq))}${field(T('يوم الاستحقاق','Due day'),inp('wzDue',w.dueDay,'number','min="1" max="28"'))}<label class="opt full"><input type="checkbox" id="wzUtil" ${w.utilities?'checked':''}><span class="sm">${T('الإيجار شامل الكهرباء والماء','Rent includes electricity & water')}</span></label>${field(T('ملاحظات وشروط إضافية','Notes & extra terms'),`<textarea class="ta" id="wzNotes">${esc(w.notes)}</textarea>`,'full')}</div>`;
  if(w.step===3){const u=unitOf(w.unit);const e=addD(addM(new Date(w.start),w.months),-1);body=`<dl class="kv" style="margin-bottom:16px"><dt>${T('الوحدة','Unit')}</dt><dd>${unitLabel(u)}</dd><dt>${T('المستأجر','Tenant')}</dt><dd>${uname(w.tenant)}</dd><dt>${T('المدة','Term')}</dt><dd>${fd(new Date(w.start))} → ${fd(e)}</dd><dt>${T('الإيجار','Rent')}</dt><dd>${money(w.rent)} / ${w.freq==='monthly'?T('شهر','mo'):T('ربع','qtr')}</dd><dt>${T('التأمين','Deposit')}</dt><dd>${money(w.deposit)}</dd><dt>${T('رسوم التسجيل (يدفعها المستأجر)','Registration fee (paid by tenant)')}</dt><dd>${money(DB.fees.reg)}</dd></dl>${padHtml()}<label class="opt" style="margin-top:14px"><input type="checkbox" id="agree"><span class="sm">${T('أقرّ بصحة البيانات وأوافق على النموذج المعتمد','I confirm the data is correct and accept the approved template')}</span></label>`}
  return {title:T('عقد إيجار جديد','New lease contract')+` — ${names[w.step]}`,cls:'wide',aria:T('عقد جديد','New contract'),body:dots+body,foot:`${w.step>0?`<button class="btn" data-a="wzback">${T('السابق','Back')}</button>`:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button>`}${w.step<3?`<button class="btn pri" data-a="wznext" ${w.step===0&&!vac.length?'disabled':''}>${T('التالي','Next')}</button>`:`<button class="btn brand" data-a="wzdone">${ic('pen',16)}${T('وقّع وأرسل للمستأجر','Sign & send to tenant')}</button>`}`};
};
function wzRead(){const w=S.modal.w;if(w.step===0){const r=document.querySelector('input[name=wzU]:checked');if(r){w.unit=r.value;const u=unitOf(w.unit);w.rent=u.rent;w.deposit=u.rent}}
  if(w.step===1)w.tenant=val('wzT')||w.tenant;
  if(w.step===2){w.start=val('wzStart');w.months=+val('wzMonths');w.rent=+val('wzRent');w.deposit=+val('wzDep');w.freq=val('wzFreq');w.dueDay=+val('wzDue')||1;w.utilities=chk('wzUtil');w.notes=val('wzNotes')}return w}
A.wznext=()=>{const w=wzRead();if(w.step===0&&!w.unit){toast(T('اختر وحدة','Pick a unit'),true);return}if(w.step===2&&(!w.start||w.rent<=0)){toast(T('أكمل تاريخ البداية والإيجار','Fill in the start date and rent'),true);return}w.step++;rerenderModal();if(w.step===3)initPad()};
A.wzback=()=>{wzRead();S.modal.w.step--;rerenderModal()};
A.wzdone=async()=>{if(!PAD.ink){toast(T('ارسم توقيعك أولاً','Draw your signature first'),true);return}if(!chk('agree')){toast(T('يجب الموافقة على الإقرار','Please accept the declaration'),true);return}
  const w=S.modal.w;
  try{
    const r=await API.post('/api/contracts',{unitId:w.unit,tenantId:w.tenant,start:w.start,months:w.months,rent:w.rent,deposit:w.deposit,dueDay:w.dueDay,freq:w.freq,utilities:w.utilities,notes:w.notes});
    await refresh();S.modal=null;S.f.contracts.st='all';render();openModal('contract',{id:r.contract.id});toast(T('تم إنشاء العقد وإرساله للمستأجر','Contract created and sent to the tenant'))
  }catch(e){apiError(e,'تعذّر إنشاء العقد','Could not create the contract')}};

/* ===== payments ===== */
V.payments=()=>S.role==='tenant'?payTenant():S.role==='landlord'?payLandlord():payAdmin();
function payLandlord(){
  const F=S.f.payments;const all=myPays().filter(p=>p.kind==='rent'&&p.status!=='upcoming'&&days(TODAY,p.due)<=120);const l=all.filter(p=>(F.st==='all'||p.status===F.st)&&(!F.q||(uname(ctOf(p.c).tenant)+ctOf(p.c).no).toLowerCase().includes(F.q.toLowerCase()))).sort((a,b)=>b.due-a.due);
  const cm=curMonthPays();const exp=cm.reduce((a,p)=>a+p.amount,0),col=cm.filter(p=>p.status==='paid').reduce((a,p)=>a+p.amount,0);const over=all.filter(p=>p.status==='overdue');const up=myPays().filter(p=>p.status==='due'&&p.kind==='rent');
  return pageHead(T('المدفوعات','Payments'),T('تابع تحصيل الإيجارات والمتأخرات','Track rent collection and arrears'),btn(T('تصدير','Export'),'modal',{t:'export',kind:'payments'},'','download')+btn(T('تذكير بالمتأخرات','Remind all overdue'),'remindall','','pri','send'))+
  `<div class="kpis">${kpi(T('المتوقع هذا الشهر','Expected this month'),`${fmt(exp)}<small>${cur()}</small>`,'','coins')}${kpi(T('المحصّل','Collected'),`${fmt(col)}<small>${cur()}</small>`,T(`نسبة التحصيل ${pct(col,exp)}%`,`Collection rate ${pct(col,exp)}%`),'check')}${kpi(T('متأخر','Overdue'),`${fmt(over.reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,T(`${over.length} دفعات`,`${over.length} payments`),'alert')}${kpi(T('مستحق قريباً','Due soon'),`${fmt(up.reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,T(`${up.length} دفعات خلال 30 يوماً`,`${up.length} payments in 30 days`),'clock')}</div>
  <div class="tb" style="margin-top:20px">${searchBox('pyQ',F.q,T('ابحث باسم المستأجر أو رقم العقد…','Search tenant or contract…'),'py')}${seg([['all',T('الكل','All'),all.length],['overdue',T('متأخرة','Overdue'),all.filter(p=>p.status==='overdue').length],['due',T('مستحقة','Due'),all.filter(p=>p.status==='due').length],['paid',T('مدفوعة','Paid'),all.filter(p=>p.status==='paid').length]],F.st,'seg','data-k="payments.st"')}</div>
  ${table([{h:T('المستأجر','Tenant'),f:p=>{const c=ctOf(p.c);const n=uname(c.tenant);return `<div class="ent">${ava(n)}<div><b>${esc(n)}</b><small>${esc(c.no)}</small></div></div>`}},{h:T('الوحدة','Unit'),f:p=>{const u=unitOf(ctOf(p.c).unit);return `${L(UT[u.type])} ${esc(u.no)}`}},{h:T('الاستحقاق','Due'),f:p=>`${fd(p.due)}<small class="xs mut3" style="display:block">${p.status==='paid'?T('دُفعت','Paid')+' '+fd(p.paidOn):dayLbl(days(p.due,TODAY))}</small>`},{h:T('المبلغ','Amount'),f:p=>`<b class="num">${money(p.amount)}</b>`},{h:T('الحالة','Status'),f:p=>PST(p.status)},{h:'',c:'ac',f:p=>p.status==='paid'?ibtn('receipt','dlreceipt',{id:p.id},T('الإيصال','Receipt')):btn(T('تذكير','Remind'),'remind',{id:p.id},'sm')+' '+btn(T('استلام نقدي','Mark received'),'modal',{t:'confirm',title:T('تأكيد الاستلام','Confirm receipt'),text:T('هل استلمت هذه الدفعة نقداً أو بتحويل خارجي؟','Did you receive this payment in cash or by external transfer?'),act:'markpaid',id:p.id,label:T('تأكيد الاستلام','Confirm')},'sm')}],l)}`;
}
IN.py=v=>{S.f.payments.q=v;renderView()};
A.remind=async d=>{const p=DB.payments.find(x=>x.id===d.id),c=ctOf(p.c);try{await API.post('/api/payments/'+d.id+'/remind');toast(T('تم إرسال التذكير إلى '+uname(c.tenant),'Reminder sent to '+uname(c.tenant)))}catch(e){apiError(e,'تعذّر الإرسال','Could not send')}};
A.remindall=async()=>{try{const r=await API.post('/api/payments/remind-all');if(!r.count){toast(T('لا توجد متأخرات','No overdue payments'));return}toast(T(`تم إرسال ${r.count} تذكير`,`${r.count} reminders sent`))}catch(e){apiError(e,'تعذّر الإرسال','Could not send')}};
A.markpaid=async d=>{try{await afterMutation(API.post('/api/payments/'+d.id+'/mark-cash'));closeModal();toast(T('تم تسجيل الدفعة','Payment recorded'))}catch(e){apiError(e,'تعذّر التسجيل','Could not record the payment')}};
const METH={benefit:['بنفاذ / Benefit Pay','Benefit Pay'],card:['بطاقة ائتمان','Credit card'],bank:['تحويل بنكي','Bank transfer'],cash:['نقداً','Cash']};
function payTenant(){
  const all=myPays().sort((a,b)=>a.due-b.due);const openP=all.filter(p=>p.status!=='paid'&&p.status!=='upcoming'||(p.kind==='fee'&&p.status!=='paid'));const nxt=all.filter(p=>p.status==='upcoming'&&p.kind==='rent').slice(0,2);const hist=all.filter(p=>p.status==='paid').sort((a,b)=>b.due-a.due);
  const y=hist.filter(p=>p.paidOn&&p.paidOn.getFullYear()===TODAY.getFullYear()).reduce((a,p)=>a+p.amount,0);
  return pageHead(T('المدفوعات','Payments'),T('ادفع إيجارك وحمّل إيصالاتك','Pay your rent and get your receipts'),btn(T('تصدير','Export'),'modal',{t:'export',kind:'payments'},'','download'))+
  `<div class="kpis">${kpi(T('المستحق الآن','Due now'),`${fmt(openP.reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,T(`${openP.length} دفعات`,`${openP.length} payments`),'coins')}${kpi(T('المدفوع في '+TODAY.getFullYear(),'Paid in '+TODAY.getFullYear()),`${fmt(y)}<small>${cur()}</small>`,'','check')}${kpi(T('السداد التلقائي','Auto-pay'),DB.autopay?T('مفعّل','On'):T('متوقف','Off'),`<label class="row" style="gap:8px">${sw(!!DB.autopay,'autopay')}<span>${T('تبديل','Toggle')}</span></label>`,'refresh')}</div>
  <div class="card" style="margin-top:20px"><div class="ch"><h3>${T('دفعات مستحقة وقادمة','Due & upcoming')}</h3></div>${[...openP,...nxt].map(p=>`<div class="li"><span class="ii ${p.status==='overdue'?'bad':p.status==='due'?'info':''}">${ic(p.kind==='fee'?'file':'card',17)}</span><div class="tx"><div class="sm b">${p.kind==='fee'?T('رسوم تسجيل العقد','Contract registration fee')+' · '+ctOf(p.c).no:mon(p.due.getMonth(),1)+' '+p.due.getFullYear()+' — '+T('إيجار','Rent')}</div><div class="xs mut3">${fd(p.due)} · ${dayLbl(days(p.due,TODAY))}</div></div><b class="num">${money(p.amount)}</b>${PST(p.status)}${p.status!=='upcoming'?btn(T('ادفع','Pay'),'modal',{t:'pay',id:p.id},'sm brand'):''}</div>`).join('')||empty(T('لا مبالغ مستحقة','Nothing due'),'','check')}</div>
  <h3 style="margin:24px 0 12px">${T('سجل المدفوعات','Payment history')}</h3>
  ${table([{h:T('الفترة','Period'),f:p=>p.kind==='fee'?T('رسوم تسجيل','Registration fee'):mon(p.due.getMonth(),1)+' '+p.due.getFullYear()},{h:T('تاريخ السداد','Paid on'),f:p=>fd(p.paidOn)},{h:T('الوسيلة','Method'),f:p=>T(...METH[p.method]||['—','—'])},{h:T('الإيصال','Receipt'),f:p=>`<span class="num" dir="ltr">${p.receipt}</span>`},{h:T('المبلغ','Amount'),f:p=>`<b class="num">${money(p.amount)}</b>`},{h:'',c:'ac',f:p=>ibtn('download','dlreceipt',{id:p.id},T('تنزيل الإيصال','Download receipt'))}],hist.slice(0,12))}`;
}
MOD.pay=d=>{
  const p=DB.payments.find(x=>x.id===d.id);const c=ctOf(p.c);const st=S.modal.stage||'form';
  if(st==='proc')return {head:false,cls:'narrow',body:`<div class="tc" style="padding:28px 0"><div class="spin"></div><h3 style="margin-top:18px">${T('جارٍ معالجة الدفع…','Processing payment…')}</h3><p class="mut sm">${T('لا تغلق هذه النافذة','Please keep this window open')}</p></div>`};
  if(st==='done')return {head:false,cls:'narrow',body:`<div class="tc" style="padding:12px 0"><div class="av lg" style="margin:0 auto 14px;background:var(--oksoft);color:var(--ok)">${ic('check',30)}</div><h3>${T('تمت العملية بنجاح','Payment successful')}</h3><p class="mut" style="margin:6px 0 16px">${T('تم تحصيل','We received')} ${money(p.amount)}</p><dl class="kv" style="text-align:start"><dt>${T('رقم الإيصال','Receipt no.')}</dt><dd class="num" dir="ltr">${p.receipt}</dd><dt>${T('العقد','Contract')}</dt><dd dir="ltr">${esc(c.no)}</dd><dt>${T('الوسيلة','Method')}</dt><dd>${T(...METH[p.method])}</dd><dt>${T('التاريخ','Date')}</dt><dd>${fd(TODAY)}</dd></dl></div>`,foot:`<button class="btn" data-a="dlreceipt" data-id="${p.id}">${ic('download',16)}${T('تنزيل الإيصال','Download receipt')}</button><button class="btn pri" data-a="close">${T('تم','Done')}</button>`};
  return {title:T('الدفع الإلكتروني','Secure payment'),cls:'narrow',body:`<div class="card" style="background:var(--sf2);margin-bottom:16px"><div class="cb row"><div style="flex:1"><div class="sm mut">${p.kind==='fee'?T('رسوم تسجيل العقد','Contract registration fee'):T('إيجار','Rent')+' · '+fd(p.due)}</div><div class="xs mut3" dir="ltr">${esc(c.no)}</div></div><b style="font-size:22px" class="num">${money(p.amount)}</b></div></div>
   <div class="col" style="gap:8px">${['benefit','card','bank'].map((m,i)=>`<label class="opt"><input type="radio" name="pm" value="${m}" ${i===0?'checked':''} data-ch="pmsel"><span class="b" style="flex:1">${T(...METH[m])}</span>${ic(m==='bank'?'building':'card',18)}</label>`).join('')}</div>
   <div id="cardF" class="fg" style="margin-top:14px">${field(T('رقم البطاقة','Card number'),inp('cn',demoOn()?'4111 1111 1111 1111':'','text','inputmode="numeric" dir="ltr" style="text-align:start"'),'full')}${field(T('تاريخ الانتهاء','Expiry'),inp('ce',demoOn()?'12/28':'','text','dir="ltr" style="text-align:start"'))}${field('CVV',inp('cv',demoOn()?'123':'','password','dir="ltr" style="text-align:start"'))}</div><div class="hint" style="margin-top:10px">${ic('lock',13)} ${demoOn()?T('بيانات تجريبية — لا يتم خصم أي مبلغ فعلي','Demo data — no real charge is made'):T('بوابة الدفع غير مربوطة بعد — يُسجَّل السداد في النظام دون خصم فعلي','Payment gateway not connected yet — the payment is recorded in the system without a real charge')}</div>`,
   foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn brand" data-a="paynow" data-id="${p.id}">${ic('lock',16)}${T('ادفع','Pay')} ${money(p.amount)}</button>`};
};
CH.pmsel=()=>{const m=document.querySelector('input[name=pm]:checked');const f=$('#cardF');if(f)f.style.display=m&&m.value==='card'?'':'none'};
A.paynow=async d=>{const m=(document.querySelector('input[name=pm]:checked')||{}).value||'benefit';S.modal.stage='proc';rerenderModal();
  const wait=new Promise(res=>setTimeout(res,1000));
  try{
    const [r]=await Promise.all([API.post('/api/payments/'+d.id+'/pay',{method:m}),wait]);
    await refresh();
    if(S.modal&&S.modal.t==='pay'){S.modal.stage='done';S.modal.d.id=r.payment.id;rerenderModal();render()}
  }catch(e){closeModal();apiError(e,'تعذّر تنفيذ الدفع','Could not process the payment')}};

/* ===== renewals ===== */
V.renewals=()=>S.role==='tenant'?renewTenant():renewLandlord();
function renewLandlord(){
  const q=S.f.contracts.q.toLowerCase();const l=myContracts().filter(c=>c.status==='active'&&days(end(c),TODAY)<=120&&days(end(c),TODAY)>=0).filter(c=>{if(!q)return true;const p=propOf(unitOf(c.unit).prop);return (uname(c.tenant)+p.name.ar+p.name.en+AREAS[p.area].ar+AREAS[p.area].en+c.no).toLowerCase().includes(q)}).sort((a,b)=>end(a)-end(b));
  const RS=c=>!c.renewal?chip(T('لم يُرسل','No action'),'nd'):chip({requested:T('طلب من المستأجر','Tenant requested'),offered:T('عرض مُرسل','Offer sent'),accepted:T('تم التجديد','Renewed'),declined:T('مرفوض','Declined')}[c.renewal.state],{requested:'warn',offered:'info',accepted:'ok',declined:'bad'}[c.renewal.state]);
  return pageHead(T('التجديد','Renewals'),T('العقود التي تنتهي خلال 120 يوماً وحالة التجديد','Leases ending within 120 days and their renewal status'))+
  (S.f.contracts.q?`<div class="tb"><span class="chip brand nd">${T('تصفية','Filter')}: ${esc(S.f.contracts.q)}</span><button class="btn sm ghost" data-a="clearq">${T('إزالة التصفية','Clear filter')}</button></div>`:'')+
  table([{h:T('المستأجر','Tenant'),f:c=>`<div class="ent">${ava(uname(c.tenant))}<div><b>${uname(c.tenant)}</b><small>${esc(c.no)}</small></div></div>`},{h:T('الوحدة','Unit'),f:c=>{const u=unitOf(c.unit);return `${L(UT[u.type])} ${esc(u.no)}<small class="xs mut3" style="display:block">${L(propOf(u.prop).name)}</small>`}},{h:T('ينتهي في','Ends'),f:c=>{const n=days(end(c),TODAY);return `${fd(end(c))}<div class="pg ${n<=30?'b':n<=60?'w':''}" style="margin-top:6px;width:120px"><i style="width:${Math.max(6,100-n/1.2)}%"></i></div><small class="xs mut3">${T(`${n} يوماً`,`${n} days`)}</small>`}},{h:T('الإيجار','Rent'),f:c=>`<b class="num">${money(c.rent)}</b>${c.renewal&&c.renewal.rent?`<small class="xs up" style="display:block">→ ${money(c.renewal.rent)}</small>`:''}`},{h:T('الحالة','Status'),f:RS},{h:'',c:'ac',f:c=>c.renewal&&['accepted','offered'].includes(c.renewal.state)?btn(T('التفاصيل','Details'),'modal',{t:'contract',id:c.id},'sm'):btn(c.renewal&&c.renewal.state==='requested'?T('الرد على الطلب','Respond'):T('إرسال عرض','Send offer'),'modal',{t:'renewoffer',id:c.id},'sm pri')}],l,empty(T('لا توجد عقود قريبة الانتهاء','No leases ending soon'),T('ستظهر هنا العقود قبل انتهائها بـ 120 يوماً.','Leases appear here 120 days before they end.'),'refresh'));
}
A.clearq=()=>{S.f.contracts.q='';renderView()};
MOD.renewoffer=d=>{const c=ctOf(d.id);const rq=c.renewal&&c.renewal.state==='requested';return {title:T('عرض تجديد','Renewal offer'),cls:'narrow',body:`<p class="mut sm" style="margin-bottom:14px">${uname(c.tenant)} · ${esc(c.no)}${rq?' · '+T('بناءً على طلب المستأجر','requested by the tenant'):''}</p><div class="fg">${field(T('مدة التجديد','New term'),sel('roM',[[6,'6 '+T('أشهر','months')],[12,'12 '+T('شهراً','months')],[24,'24 '+T('شهراً','months')]],12))}${field(T('الإيجار الجديد (د.ب)','New rent (BD)'),inp('roR',c.rent,'number','min="1" data-in="rodelta"'))}<div class="full sm" id="roDelta" style="color:var(--ink2)">${T('بدون تغيير في الإيجار','No change in rent')}</div>${field(T('رسالة للمستأجر','Message to tenant'),`<textarea class="ta" id="roMsg" style="min-height:70px">${T('يسعدنا تجديد العقد بنفس الشروط.','We would be glad to renew on the same terms.')}</textarea>`,'full')}</div><input type="hidden" id="roOld" value="${c.rent}">`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="sendoffer" data-id="${c.id}">${ic('send',16)}${T('إرسال العرض','Send offer')}</button>`}};
IN.rodelta=v=>{const o=+val('roOld'),n=+v;const p=o?Math.round((n-o)/o*1000)/10:0;const e=$('#roDelta');if(e)e.textContent=p===0?T('بدون تغيير في الإيجار','No change in rent'):(p>0?T(`زيادة ${p}% عن الإيجار الحالي`,`${p}% increase on current rent`):T(`تخفيض ${-p}% عن الإيجار الحالي`,`${-p}% reduction on current rent`))};
A.sendoffer=async d=>{const c=ctOf(d.id);try{await afterMutation(API.post('/api/contracts/'+d.id+'/renew-offer',{rent:+val('roR')||c.rent,months:+val('roM')}));closeModal();toast(T('تم إرسال عرض التجديد','Renewal offer sent'))}catch(e){apiError(e,'تعذّر الإرسال','Could not send the offer')}};
function renewTenant(){
  const cs=myContracts().filter(c=>c.status==='active');
  return pageHead(T('تجديد العقد','Lease renewal'),T('اطلب التجديد أو راجع عرض المؤجر','Request renewal or review the landlord’s offer'))+(cs.map(c=>{const n=days(end(c),TODAY);const r=c.renewal;
   return `<div class="card" style="margin-bottom:16px"><div class="cb col"><div class="row wrapf"><div style="flex:1"><b>${unitLabel(unitOf(c.unit))}</b><div class="sm mut" dir="ltr" style="text-align:start">${esc(c.no)}</div></div>${CSTATUS(cst(c))}</div>
   <div class="row wrapf" style="gap:24px"><div><div class="xs mut3">${T('ينتهي في','Ends on')}</div><b>${fd(end(c))}</b></div><div><div class="xs mut3">${T('المتبقي','Remaining')}</div><b>${T(`${n} يوماً`,`${n} days`)}</b></div><div><div class="xs mut3">${T('الإيجار الحالي','Current rent')}</div><b>${money(c.rent)}</b></div></div>
   ${r&&r.state==='offered'?`<div class="verres ok" style="background:var(--infosoft);color:var(--info)">${ic('refresh',24)}<div style="flex:1"><b>${T('لديك عرض تجديد من المؤجر','You have a renewal offer')}</b><div class="sm" style="color:var(--ink)">${T(`مدة ${r.months} شهراً بإيجار ${money(r.rent)} شهرياً`,`${r.months} months at ${money(r.rent)} per month`)}</div><div class="row wrapf" style="margin-top:10px">${btn(T('قبول العرض','Accept offer'),'acceptoffer',{id:c.id},'pri sm','check')}${btn(T('رفض','Decline'),'declineoffer',{id:c.id},'sm danger')}</div></div></div>`
   :r&&r.state==='requested'?`<div class="verres" style="background:var(--goldsoft);color:var(--gold)">${ic('clock',22)}<div><b style="color:var(--ink)">${T('تم إرسال طلبك','Your request was sent')}</b><div class="sm" style="color:var(--ink)">${T('بانتظار عرض المؤجر.','Waiting for the landlord’s offer.')}</div></div></div>`
   :r&&r.state==='accepted'?`<div class="verres ok">${ic('check',22)}<div><b>${T('تم تجديد العقد','Lease renewed')}</b></div></div>`
   :n<=90?`<div>${btn(T('طلب تجديد','Request renewal'),'crenew',{id:c.id},'pri','refresh')}</div>`:`<div class="sm mut">${T('يمكنك طلب التجديد قبل انتهاء العقد بـ 90 يوماً.','You can request renewal 90 days before the lease ends.')}</div>`}</div></div>`}).join('')||`<div class="card">${empty(T('لا توجد عقود فعّالة','No active contracts'),'','file')}</div>`);
}
A.acceptoffer=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/renew-accept'));toast(T('تم تجديد العقد وتحديث تاريخ الانتهاء','Lease renewed and end date updated'))}catch(e){apiError(e,'تعذّر التنفيذ','Could not accept the offer')}};
A.declineoffer=async d=>{try{await afterMutation(API.post('/api/contracts/'+d.id+'/renew-decline'));toast(T('تم رفض العرض','Offer declined'))}catch(e){apiError(e,'تعذّر التنفيذ','Could not decline the offer')}};

/* ===== maintenance ===== */
V.maintenance=()=>S.role==='tenant'?maintTenant():maintBoard();
const steps4=['new','assigned','in_progress','done'];
function maintBoard(){
  const q=S.f.maint.q.toLowerCase();const all=myMaint().filter(m=>!q||(L(m.title)+unitLabel(unitOf(m.unit))+uname(m.by)).toLowerCase().includes(q));
  const col=(st,ti)=>{const l=all.filter(m=>m.st===st);return `<div class="kc"><h4><span>${ti}</span><span class="num">${l.length}</span></h4>${l.map(m=>`<div class="kt"><div class="row" style="align-items:flex-start"><b class="sm" style="flex:1">${L(m.title)}</b>${PRI(m.pri)}</div><div class="xs mut3" style="margin:6px 0">${unitLabel(unitOf(m.unit))}<br>${uname(m.by)} · ${rel(m.created)}</div><div class="row wrapf" style="gap:6px">${chip(rawL(CAT[m.cat]),'nd')}${m.tech?chip(m.tech,'teal nd'):''}</div><div class="row" style="margin-top:10px;gap:6px">${btn(T('التفاصيل','Details'),'modal',{t:'maint',id:m.id},'sm')}${st!=='done'?btn(st==='new'?T('تعيين فني','Assign'):st==='assigned'?T('بدء العمل','Start'):T('إنجاز','Complete'),'madv',{id:m.id},'sm pri'):(m.rating?`<span class="xs" style="color:var(--gold)">${'★'.repeat(m.rating)}</span>`:'')}</div></div>`).join('')||`<div class="xs mut3 tc" style="padding:20px 0">${T('لا طلبات','No requests')}</div>`}</div>`};
  return pageHead(T('الصيانة','Maintenance'),T('تابع طلبات الصيانة وعيّن الفنيين حتى الإغلاق','Follow requests and assign technicians until closed'))+
  `<div class="tb">${searchBox('mtQ',S.f.maint.q,T('ابحث في الطلبات…','Search requests…'),'mt')}</div><div class="kb">${col('new',T('جديدة','New'))}${col('assigned',T('تم التعيين','Assigned'))}${col('in_progress',T('قيد التنفيذ','In progress'))}${col('done',T('مكتملة','Done'))}</div>`;
}
IN.mt=v=>{S.f.maint.q=v;renderView()};
function maintTenant(){
  const l=myMaint().sort((a,b)=>b.created-a.created);
  return pageHead(T('طلبات الصيانة','Maintenance requests'),T('أبلغ عن أي عطل وتابع حالته حتى الإغلاق','Report a problem and follow it until closed'),btn(T('طلب جديد','New request'),'modal',{t:'maintnew'},'brand','plus'))+
  (l.map(m=>{const i=steps4.indexOf(m.st);return `<div class="card" style="margin-bottom:14px"><div class="cb col"><div class="row wrapf"><div style="flex:1;min-width:200px"><b>${L(m.title)}</b><div class="xs mut3">${L(CAT[m.cat])} · ${rel(m.created)}${m.tech?' · '+esc(m.tech):''}</div></div>${PRI(m.pri)}${MST(m.st)}</div>
   <div class="steps-w" style="margin:0">${steps4.map((s,k)=>`<i class="${k<=i?'on':''}"></i>`).join('')}</div><div class="row xs mut3"><span class="sp">${T('جديد','New')}</span><span class="sp tc">${T('تعيين فني','Assigned')}</span><span class="sp tc">${T('قيد التنفيذ','In progress')}</span><span class="sp" style="text-align:end">${T('مكتمل','Done')}</span></div>
   ${m.st==='done'?`<div class="row wrapf"><span class="sm mut">${m.rating?T('تقييمك','Your rating'):T('قيّم الخدمة','Rate the service')}</span>${[1,2,3,4,5].map(n=>`<button class="btn sm ghost ico" data-a="rate" data-id="${m.id}" data-v="${n}" aria-label="${n}" style="color:${n<=m.rating?'var(--gold)':'var(--ink3)'};font-size:18px">${n<=m.rating?'★':'☆'}</button>`).join('')}</div>`:''}</div></div>`}).join('')||`<div class="card">${empty(T('لا توجد طلبات','No requests'),T('كل شيء يعمل بشكل جيد!','Everything is working fine!'),'wrench')}</div>`);
}
A.rate=async d=>{try{await afterMutation(API.post('/api/maintenance/'+d.id+'/rate',{rating:+d.v}));toast(T('شكراً لتقييمك','Thanks for your rating'))}catch(e){apiError(e,'تعذّر حفظ التقييم','Could not save the rating')}};
MOD.maintnew=()=>({title:T('طلب صيانة جديد','New maintenance request'),body:`<div class="fg">${field(T('التصنيف','Category'),sel('mCat',Object.keys(CAT).map(k=>[k,L(CAT[k])]),'ac'))}${field(T('الأولوية','Priority'),sel('mPri',[['low',T('منخفضة','Low')],['normal',T('عادية','Normal')],['high',T('عاجلة','Urgent')]],'normal'))}${field(T('عنوان المشكلة','Problem title'),inp('mTitle','','text','data-focus'),'full')}${field(T('الوصف','Description'),`<textarea class="ta" id="mDesc"></textarea>`,'full')}<div class="fld full"><label class="lb">${T('صورة (اختياري)','Photo (optional)')}</label><input type="file" class="in" id="mPhoto" accept="image/*"></div></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn brand" data-a="mtsave">${ic('send',16)}${T('إرسال الطلب','Submit request')}</button>`});
A.mtsave=async()=>{const t=val('mTitle').trim();if(!t){toast(T('اكتب عنوان المشكلة','Enter a problem title'),true);return}
  try{await afterMutation(API.post('/api/maintenance',{title:t,category:val('mCat'),priority:val('mPri')}));closeModal();S.view='maintenance';render();toast(T('تم إرسال طلب الصيانة','Request submitted'))}catch(e){apiError(e,'تعذّر إرسال الطلب','Could not submit the request')}};
MOD.maint=d=>{const m=DB.maint.find(x=>x.id===d.id);const i=steps4.indexOf(m.st);const mine=S.role!=='tenant';
  return {title:L(m.title),cls:'narrow',body:`<div class="row wrapf" style="margin-bottom:14px">${MST(m.st)}${PRI(m.pri)}${chip(rawL(CAT[m.cat]),'nd')}</div><dl class="kv"><dt>${T('الوحدة','Unit')}</dt><dd>${unitLabel(unitOf(m.unit))}</dd><dt>${T('مقدّم الطلب','Requested by')}</dt><dd>${uname(m.by)}</dd><dt>${T('التاريخ','Date')}</dt><dd>${fdt(m.created)}</dd><dt>${T('الفني','Technician')}</dt><dd>${m.tech?esc(m.tech):'—'}</dd></dl>
   <hr class="hr"><ul class="tl">${[[T('تم استلام الطلب','Request received')],[T('تم تعيين فني','Technician assigned')],[T('بدء العمل','Work started')],[T('اكتمل الإصلاح','Repair completed')]].map((s,k)=>`<li class="${k<=i?'done':k===i+1?'now':''}"><i></i><div class="sm ${k<=i?'b':'mut'}">${s[0]}</div></li>`).join('')}</ul>
   ${mine&&m.st==='new'?`<hr class="hr">${field(T('تعيين فني','Assign technician'),sel('mTech',TECHS.map(t=>[t,t]),TECHS[0]))}`:''}`,
   foot:`<button class="btn" data-a="close">${T('إغلاق','Close')}</button>${mine&&m.st!=='done'?`<button class="btn pri" data-a="madv" data-id="${m.id}" data-m="1">${m.st==='new'?T('تعيين','Assign'):m.st==='assigned'?T('بدء العمل','Start work'):T('تحديد كمكتمل','Mark complete')}</button>`:''}`}};
A.madv=async d=>{const m=DB.maint.find(x=>x.id===d.id);
  try{
    if(m.st==='new'){if(!d.m){openModal('maint',{id:m.id});return}await afterMutation(API.post('/api/maintenance/'+m.id+'/assign',{technician:val('mTech')||TECHS[0]}))}
    else if(m.st==='assigned')await afterMutation(API.post('/api/maintenance/'+m.id+'/start'));
    else if(m.st==='in_progress')await afterMutation(API.post('/api/maintenance/'+m.id+'/complete'));
    closeModal();toast(T('تم تحديث حالة الطلب','Request updated'))
  }catch(e){apiError(e,'تعذّر التحديث','Could not update the request')}};

/* ===== calendar ===== */
const DOW=[['الأحد','Sun'],['الاثنين','Mon'],['الثلاثاء','Tue'],['الأربعاء','Wed'],['الخميس','Thu'],['الجمعة','Fri'],['السبت','Sat']];
V.calendar=()=>{
  const cal=S.cal||{y:TODAY.getFullYear(),m:TODAY.getMonth()};
  const {y,m}=cal;const first=new Date(y,m,1),start=addD(first,-first.getDay());const evs={};const add=(d,c,t)=>{const k=d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate();(evs[k]=evs[k]||[]).push({c,t})};
  myPays().filter(p=>p.status!=='upcoming'||true).forEach(p=>{const c=ctOf(p.c);add(p.due,p.status==='paid'?'ok':p.status==='overdue'?'bad':'',(p.kind==='fee'?T('رسوم','Fee'):T('إيجار','Rent'))+' '+(S.role==='landlord'?uname(c.tenant).split(' ')[0]:money(p.amount)))});
  myContracts().forEach(c=>{if(['active','expired'].includes(c.status))add(end(c),'warn',T('ينتهي ','Ends ')+c.no.slice(-3));if(['pending_sign','pending_pay'].includes(c.status))add(c.start,'',T('بداية عقد','Lease starts'))});
  myMaint().forEach(x=>add(x.created,'warn',T('صيانة','Repair')));
  const cells=[];for(let i=0;i<42;i++){const d=addD(start,i);const e=evs[d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate()]||[];const t=d.toDateString()===TODAY.toDateString();
    cells.push(`<div class="cd ${d.getMonth()!==m?'o':''} ${t?'t':''}"><span class="dn2">${d.getDate()}</span>${e.slice(0,3).map(x=>`<span class="ev ${x.c}">${esc(x.t)}</span>`).join('')}${e.length>3?`<span class="xs mut3">+${e.length-3}</span>`:''}</div>`)}
  const monthEv=Object.entries(evs).filter(([k])=>k.startsWith(y+'-'+m+'-')).flatMap(([k,v])=>v.map(x=>({d:+k.split('-')[2],...x}))).sort((a,b)=>a.d-b.d);
  return pageHead(T('التقويم','Calendar'),T('مواعيد السداد وانتهاء العقود والصيانة','Payment dates, lease expiries and repairs'),`<div class="row">${ibtn(S.lang==='ar'?'right':'left','calnav',{v:-1},T('السابق','Previous'))}<b style="min-width:130px;text-align:center">${mon(m,1)} ${y}</b>${ibtn(S.lang==='ar'?'left':'right','calnav',{v:1},T('التالي','Next'))}${btn(T('اليوم','Today'),'calnav',{v:0},'sm')}</div>`)+
  `<div class="legend" style="margin-bottom:10px"><span><i style="background:var(--ok)"></i>${T('مدفوعة','Paid')}</span><span><i style="background:var(--info)"></i>${T('مستحقة','Due')}</span><span><i style="background:var(--bad)"></i>${T('متأخرة','Overdue')}</span><span><i style="background:var(--warn)"></i>${T('عقود وصيانة','Leases & repairs')}</span></div>
  <div class="cal">${DOW.map(d=>`<div class="h">${T(d[0],d[1])}</div>`).join('')}${cells.join('')}</div>
  <div class="card" style="margin-top:20px"><div class="ch"><h3>${T('أحداث الشهر','This month')}</h3></div>${monthEv.map(e=>`<div class="li"><span class="ii ${e.c||'info'}">${ic('calendar',16)}</span><div class="tx sm"><b>${e.d} ${mon(m)}</b> — ${esc(e.t)}</div></div>`).join('')||empty(T('لا أحداث في هذا الشهر','No events this month'),'','calendar')}</div>`;
};
A.calnav=d=>{const v=+d.v;if(v===0)S.cal={y:TODAY.getFullYear(),m:TODAY.getMonth()};else{const n=new Date(S.cal.y,S.cal.m+v,1);S.cal={y:n.getFullYear(),m:n.getMonth()}}renderView()};

/* ===== reports ===== */
V.reports=()=>S.role==='admin'?reportsAdmin():reportsLandlord();
function reportsLandlord(){
  const inc=incomeSeries(12);const units=myUnits();const st={occupied:0,vacant:0,reserved:0,maint:0};units.forEach(u=>st[unitStatus(u)]++);const tot=inc.reduce((a,i)=>a+i.paid,0);const ex=inc.reduce((a,i)=>a+i.exp,0);
  const months=[];for(let i=0;i<6;i++){const d=addM(new Date(TODAY.getFullYear(),TODAY.getMonth(),1),i);months.push({l:mon(d.getMonth()),v:myContracts().filter(c=>['active'].includes(c.status)&&monthKey(end(c))===monthKey(d)).length})}
  return pageHead(T('التقارير','Reports'),T('أداء محفظتك العقارية خلال آخر 12 شهراً','Your portfolio performance over the last 12 months'),btn(T('تصدير الدخل','Export income'),'modal',{t:'export',kind:'income'},'pri','download'))+
  `<div class="kpis">${kpi(T('إجمالي المحصّل','Total collected'),`${fmt(tot)}<small>${cur()}</small>`,T('آخر 12 شهراً','Last 12 months'),'coins')}${kpi(T('نسبة التحصيل','Collection rate'),pct(tot,ex)+'%','','check')}${kpi(T('متوسط الإيجار','Average rent'),`${fmt(Math.round(myContracts().filter(c=>c.status==='active').reduce((a,c)=>a+c.rent,0)/Math.max(1,myContracts().filter(c=>c.status==='active').length)))}<small>${cur()}</small>`,'','tag')}${kpi(T('عقود فعّالة','Active leases'),myContracts().filter(c=>c.status==='active').length,'','file')}</div>
  <div class="g2"><div class="card"><div class="ch"><h3>${T('الإيرادات الشهرية','Monthly income')}</h3><div class="legend"><span><i style="background:var(--teal)"></i>${T('المحصّل','Collected')}</span><span><i style="background:var(--line)"></i>${T('المتوقع','Expected')}</span></div></div><div class="cb">${barChart(inc.map(i=>i.l),[inc.map(i=>i.exp),inc.map(i=>i.paid)],['var(--line)','var(--teal)'],{label:T('الإيرادات','Income')})}</div></div>
  <div class="card"><div class="ch"><h3>${T('حالة الوحدات','Unit status')}</h3></div><div class="cb row wrapf" style="justify-content:center;gap:24px">${donut([{v:st.occupied,c:'var(--teal)',l:T('مؤجرة','Let')},{v:st.reserved,c:'var(--info)',l:T('محجوزة','Reserved')},{v:st.vacant,c:'var(--warn)',l:T('شاغرة','Vacant')},{v:st.maint,c:'var(--bad)',l:T('صيانة','Maint.')}],units.length,T('وحدة','units'))}<div class="col" style="gap:6px" ><div class="legend" style="flex-direction:column;gap:6px"><span><i style="background:var(--teal)"></i>${T('مؤجرة','Let')} ${st.occupied}</span><span><i style="background:var(--info)"></i>${T('محجوزة','Reserved')} ${st.reserved}</span><span><i style="background:var(--warn)"></i>${T('شاغرة','Vacant')} ${st.vacant}</span><span><i style="background:var(--bad)"></i>${T('صيانة','Maintenance')} ${st.maint}</span></div></div></div></div></div>
  <div class="g2e"><div class="card"><div class="ch"><h3>${T('عقود تنتهي — الأشهر الستة القادمة','Leases ending — next 6 months')}</h3></div><div class="cb">${barChart(months.map(m=>m.l),[months.map(m=>m.v)],['var(--brand)'],{h:200,label:T('عقود','Leases')})}</div></div>
  <div class="card"><div class="ch"><h3>${T('الدخل حسب العقار','Income by property')}</h3></div><div class="cb">${hbars(myProps().map(p=>({l:L(p.name),v:DB.units.filter(u=>u.prop===p.id&&unitStatus(u)==='occupied').reduce((a,u)=>a+u.rent,0),t:money(DB.units.filter(u=>u.prop===p.id&&unitStatus(u)==='occupied').reduce((a,u)=>a+u.rent,0))})),'var(--teal)')}</div></div></div>`;
}
